describe('File Download Functionality', () => {
    const downloadUrl = '/api/export'; // Adjust the URL as necessary

    beforeEach(() => {
        cy.visit('/your-page-url'); // Replace with the actual page URL
    });

    it('should trigger file download when export button is clicked', () => {
        cy.intercept('GET', downloadUrl).as('fileDownload');

        cy.get('button#export-button').click(); // Replace with the actual selector for the export button

        cy.wait('@fileDownload').then((interception) => {
            expect(interception.response.statusCode).to.eq(200);
            expect(interception.response.headers['content-type']).to.include('application/octet-stream');
        });

        cy.get('a[download]').should('exist'); // Check if the download link is present
    });

    it('should handle file download failure gracefully', () => {
        cy.intercept('GET', downloadUrl, {
            statusCode: 500,
            body: { error: 'Internal Server Error' }
        }).as('fileDownloadError');

        cy.get('button#export-button').click(); // Replace with the actual selector for the export button

        cy.wait('@fileDownloadError').then((interception) => {
            expect(interception.response.statusCode).to.eq(500);
            cy.get('.error-message').should('contain', 'Failed to download file'); // Adjust the selector for error message
        });
    });
});
